const items = $input.all();
function norm(v) { return (v != null) ? String(v).trim() : null; }
function toDate(v) { if (!v) return null; var s = String(v).trim(); if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10); if (/^\d+$/.test(s)) { var n = parseInt(s, 10); var d = new Date(Date.UTC(1899, 11, 30) + n * 86400000); return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10); } var d = new Date(s); return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10); }
function toTime(v) { if (!v) return null; var s = String(v).trim(); if (/^\d{2}:\d{2}/.test(s)) return s.slice(0, 5); if (/^0?\.\d+$/.test(s)) { var f = parseFloat(s); var ts = Math.round(f * 86400); var h = Math.floor(ts / 3600); var m = Math.floor((ts % 3600) / 60); return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0'); } return null; }
function toInt(v) { if (!v) return null; var n = parseInt(String(v), 10); return isNaN(n) ? null : n; }
function toBool(v) { if (v == null) return null; return ['si','sí','yes','true','1'].includes(String(v).toLowerCase()); }
function col(r){var ks=Array.prototype.slice.call(arguments,1);var n=function(s){return String(s).trim().toLowerCase().replace(/[\s\u00a0]+/g,' ').replace(/[\u2013\u2014]/g,'-').normalize('NFD').replace(/[\u0300-\u036f]/g,'');};var rn={};Object.keys(r).forEach(function(k){if(r[k]!=null&&r[k]!=='')rn[n(k)]=r[k];});for(var j=0;j<ks.length;j++){if(r[ks[j]]!=null&&r[ks[j]]!=='')return r[ks[j]];var nk=n(ks[j]);if(rn[nk]!=null)return rn[nk];var rks=Object.keys(rn);for(var k=0;k<rks.length;k++){if(rks[k].startsWith(nk+' (')||rks[k].startsWith(nk+' -')||rks[k]===nk){return rn[rks[k]];}}};return null;}

return items.map(function(item) {
  var r = item.json;
  var email = norm(r['Correo del Usuario Atendido'] || r['Correo electrónico'] || r['email']);
  if (!email || !email.includes('@')) return null;
  var fecha = toDate(r['Fecha de la Sesión'] || r['Fecha'] || r['fecha_sesion']);
  if (!fecha) return null;

  var resultadoRaw = norm(r['Resultado de la sesión'] || r['resultado']) || ''; var rl = resultadoRaw.toLowerCase().trim(); var statusVal = rl.includes('cancelado') ? 'Cancelado' : rl.includes('seguimiento') ? 'En seguimiento' : 'Resuelto';

  var out = {};
  Object.assign(out, { _rpc: { p_email: email, p_full_name: norm(r['Nombre del Usuario Atendido'] || r['Nombre'] || r['full_name']) || 'Sin nombre', p_phone: norm(r['Celular del usuario atendido'] || r['Celular'] || r['phone']), p_id_num: norm(r['Cedula del Usuario Atendido'] || r['Documento de identidad']), p_nit: norm(r['Nit de la Empresa'] || r['NIT']), p_city: norm(r['Municipio'] || r['city']), p_cargo: norm(r['Cargo del Usuario Atendido'] || r['cargo']), p_company_role_level: norm(r['Nivel del Cargo'] || r['company_role_level']), p_company_role_area: norm(r['Área del Usuario Atendido'] || r['company_role_area']), p_empresa: norm(r['Nombre de la empresa'] || r['empresa']), p_sexo: norm(r['Sexo Usuario Atendido'] || r['Sexo']), p_origen: 'sesion' } });
  Object.assign(out, { _consultoria: { fecha: fecha, hora_inicio: toTime(r['Hora de inicio'] || r['hora_inicio']), hora_fin: toTime(r['Hora de finalización'] || r['hora_fin']), duracion_minutos: toInt(col(r,'Duración de la Sesión / Minutos','Duración de la sesión','duracion')), modalidad: norm(r['Modalidad de la Sesión'] || r['modalidad']) || 'Virtual', staff_name: norm(r['Consultor / Coder'] || r['staff_name']), staff_email: norm(r['Correo Institucional / Consultor'] || r['staff_email']), nivel_potencia: norm(col(r, 'Nivel de potencia', 'Nivel de Potencia')), categoria_caso: norm(r['Categoría del caso (Potencia)1'] || r['Categoría del Caso (Potencia)']), categoria_caso_uso: norm(r['Categoria del Caso de Uso'] || r['categoria_caso_uso']), status: statusVal } });
  Object.assign(out, { _registro: { id_externo: norm(r['Id'] || r['id']), pregunta: norm(r['Pregunta'] || r['pregunta']), motivo_consulta: norm(col(r,'Motivo de la Consulta','Motivo Consulta','motivo_consulta')), estado_inicial: norm(col(r,'Estado Inicial – Situación Antes de la Intervención','Estado Inicial','estado_inicial')), acciones_realizadas: norm(col(r,'Acciones Realizadas Durante la Sesión (Describir paso a paso lo trabajado, incluyendo: Prompts utilizados  Herramientas de IA empleadas  Metodología aplicada) ','Acciones Realizadas Durante la Sesión','acciones_realizadas')), resultado_final: norm(col(r,'Resultado Final – Situación Después de la Intervención','Resultado Final','resultado_final')), estimacion_impacto: norm(col(r,'Estimación del Impacto Generado','Estimacion del Impacto Generado','estimacion_impacto')), entregables: norm(r['Entregables Producidos'] || r['entregables']), cantidad_productos: toInt(r['Cantidad de nuevos productos creados'] || r['cantidad_productos']) || 0, sesion_grabada: toBool(r['¿La sesión fue grabada?'] || r['sesion_grabada']) || false, enlace_grabacion: norm(r['Enlace de Grabación'] || r['enlace_grabacion']), adjuntar_evidencia: norm(r['Adjuntar Evidencia'] || r['adjuntar_evidencia']), confirmo_no_automatizacion: toBool(r['Confirmo que este caso NO corresponde a automatización o integración de sistemas complejos.'] || r['Confirmo que este caso NO corresponde a automatización'] || r['confirmo_no_automatizacion']), duracion_sesion_minutos: toInt(col(r,'Duración de la Sesión / Minutos','Duración de la sesión','duracion')), resultado: norm(r['Resultado de la sesión'] || r['resultado']) } });
  return { json: out };
}).filter(Boolean);

const loopItem = $('Loop One by One').item.json;
const leadId = loopItem.lead_id;
const cons = loopItem._consultoria || {};
const reg = loopItem._registro || {};

const API_KEY = '{{$env.SUPABASE_SERVICE_ROLE_KEY}}';
const BASE = 'https://scydyevwjmbhtohoncuy.supabase.co/rest/v1';
const h = { apikey: API_KEY, Authorization: `Bearer ${API_KEY}`, 'Content-Type': 'application/json' };

// 1. Lookup consultor by institutional email
let consultorId = null;
if (cons.staff_email) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${BASE}/consultores?email_institucional=eq.${encodeURIComponent(cons.staff_email)}&select=id`,
    headers: h,
  });
  if (Array.isArray(res) && res.length > 0) consultorId = res[0].id;
}

// 2. Find existing consultoria — id_externo first (handles WF-3 re-runs),
// then fall back to WF-2 booking row by (lead, date).
let existingId = null;
if (reg.id_externo) {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${BASE}/consultorias?id_externo=eq.${encodeURIComponent(reg.id_externo)}&select=id&limit=1`,
    headers: h,
  });
  if (Array.isArray(rows) && rows.length > 0) existingId = rows[0].id;
}
if (!existingId && leadId && cons.fecha) {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${BASE}/consultorias?id_lead=eq.${leadId}&fecha=eq.${cons.fecha}&booking_id=not.is.null&select=id&limit=1`,
    headers: h,
  });
  if (Array.isArray(rows) && rows.length > 0) existingId = rows[0].id;
}

const fields = {};
if (leadId) fields.id_lead = leadId;
if (reg.id_externo) fields.id_externo = reg.id_externo;
if (consultorId) fields.id_consultor = consultorId;
if (cons.fecha) fields.fecha = cons.fecha;
if (cons.hora_inicio) fields.hora_inicio = cons.hora_inicio;
if (cons.hora_fin) fields.hora_fin = cons.hora_fin;
if (cons.duracion_minutos) fields.duracion_minutos = cons.duracion_minutos;
if (cons.modalidad) fields.modalidad = cons.modalidad;
if (cons.staff_name) fields.staff_name = cons.staff_name;
if (cons.staff_email) fields.staff_email = cons.staff_email;
if (cons.nivel_potencia) fields.nivel_potencia = cons.nivel_potencia;
if (cons.categoria_caso) fields.categoria_caso = cons.categoria_caso;
if (cons.categoria_caso_uso) fields.categoria_caso_uso = cons.categoria_caso_uso;
if (cons.status) fields.status = cons.status;

let row;
if (existingId) {
  const res = await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${BASE}/consultorias?id=eq.${existingId}`,
    headers: { ...h, Prefer: 'return=representation' },
    body: JSON.stringify(fields),
  });
  row = Array.isArray(res) ? res[0] : res;
} else {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE}/consultorias`,
    headers: { ...h, Prefer: 'return=representation' },
    body: JSON.stringify(fields),
  });
  row = Array.isArray(res) ? res[0] : res;
}

if (!row?.id) return [];
return [{ json: { ...row, _registro: reg } }];

const rpcItems = $input.all();
const normItems = $('Normalize Rows').all();

return rpcItems.map((item, i) => {
  const rpc = Array.isArray(item.json) ? item.json[0] : item.json;
  const leadId = rpc?.lead_id || null;
  const orig = normItems[item.pairedItem?.item ?? i]?.json || {};
  return {
    json: {
      lead_id: leadId,
      _consultoria: orig._consultoria || {},
      _registro:    orig._registro    || {}
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const d = item.json;
  const reg = d._registro || {};
  if (!d?.id) return null;
  return {
    json: {
      id_consultoria:             d.id,
      pregunta:                   reg.pregunta                  || null,
      motivo_consulta:            reg.motivo_consulta           || null,
      estado_inicial:             reg.estado_inicial            || null,
      acciones_realizadas:        reg.acciones_realizadas       || null,
      resultado_final:            reg.resultado_final           || null,
      estimacion_impacto:         reg.estimacion_impacto        || null,
      entregables:                reg.entregables               || null,
      resultado:                  reg.resultado                 || null,
      cantidad_productos:         reg.cantidad_productos        ?? 0,
      sesion_grabada:             reg.sesion_grabada            ?? false,
      enlace_grabacion:           reg.enlace_grabacion          || null,
      adjuntar_evidencia:         reg.adjuntar_evidencia        || null,
      confirmo_no_automatizacion: reg.confirmo_no_automatizacion ?? null,
      duracion_sesion_minutos:     reg.duracion_sesion_minutos ?? null
    }
  };
}).filter(Boolean);

const items = $input.all();
const prepItems = $('Prep registro_sesion').all();

const STATUS_MAP = [
  ['cancelado', 'Cancelado'],
  ['en seguimiento', 'En seguimiento'],
  ['seguimiento', 'En seguimiento'],
  ['no asisti', 'No asistió'],
  ['escalar', 'Escalar'],
  ['resuelto', 'Resuelto'],
];

return items.map((item, i) => {
  const reg = prepItems[item.pairedItem?.item ?? i]?.json || {};
  const raw = (reg.resultado || '').toLowerCase().trim();

  let status = null;
  for (const [key, val] of STATUS_MAP) {
    if (raw.includes(key)) { status = val; break; }
  }
  if (!reg.id_consultoria) return null;
  return { json: { id_consultoria: reg.id_consultoria, status } };
}).filter(Boolean);
